  // src/game/interact.js
  function findInteraction(game, p) {
    const w = game.world;
    if (p.state !== "idle") return null;
    if (p.mode === "sail") {
      const s = p.ship;
      if (!s) return null;
      const special = game.seaInteraction ? game.seaInteraction(p, s) : null;
      if (special) return special;
      const spot = findShore(w, s.x, s.y, s.def.length * 0.5 + 2.5);
      if (spot && Math.abs(s.speed) < 4.5) {
        const isl = w.islandAt(spot.x, spot.y) || w.nearestIsland(spot.x, spot.y, 40);
        return { label: `Go ashore${isl && isl.name ? " \u2014 " + isl.name : ""}`, key: "E", run: () => disembark(game, p, spot) };
      }
      return null;
    }
    const cands = [];
    for (const s of game.ships) {
      if (s.sunk || s.owner !== "player") continue;
      const d = w.distance(p.x, p.y, s.x, s.y);
      if (d < s.def.length * 0.55 + 1.6) cands.push({ d: d - 1, label: `Board the ${s.name}`, run: () => board(game, p, s) });
    }
    for (const a of game.actorsNear(p.x, p.y, 2.4)) {
      if (a === p || a.state !== "idle" || !a.talk) continue;
      if (a.provoked && a.hostileNow) continue;
      const d = w.distance(p.x, p.y, a.x, a.y);
      cands.push({ d, label: `Talk to ${a.name}`, run: () => game.emit("talk", a) });
    }
    for (const a of game.actorsNear(p.x, p.y, 2.2)) {
      if (a === p || a.state !== "knocked" || !a.canCarry) continue;
      cands.push({ d: w.distance(p.x, p.y, a.x, a.y) + 0.5, label: a.carryLabel || `Carry ${a.name}`, run: () => game.emit("carry", a) });
    }
    if (w.objects) {
      for (const o of w.objects.near(p.x, p.y, 3.2)) {
        if (o.kind === "building" && o.role && o.role !== "house" && o.door) {
          const d = w.distance(p.x, p.y, o.door.x, o.door.y + 0.3);
          if (d < 1.6) cands.push({ d, label: o.name ? `Enter ${o.name}` : "Enter", run: () => game.emit("enterBuilding", o) });
        } else if (o.kind === "building" && o.role === "house" && o.door) {
          const d = w.distance(p.x, p.y, o.door.x, o.door.y + 0.3);
          if (d < 1.2) cands.push({ d: d + 0.5, label: "Knock on the door", run: () => game.emit("knockDoor", o) });
        } else if (o.kind === "chest" && !o.opened) {
          const d = w.distance(p.x, p.y, o.x, o.y);
          if (d < 1.6) cands.push({ d, label: "Open the chest", run: () => game.emit("openChest", o) });
        } else if (o.interact) {
          const d = w.distance(p.x, p.y, o.x, o.y);
          if (d < (o.interactRange || 1.8)) cands.push({ d, label: o.interact, run: () => game.emit("useObject", o) });
        } else if (o.kind === "dummy") {
          const d = w.distance(p.x, p.y, o.x, o.y);
          if (d < 1.8) cands.push({ d: d + 0.3, label: "Train (strike the dummy)", run: () => game.emit("trainDummy", o) });
        }
      }
    }
    for (const it of game.groundItems || []) {
      const d = w.distance(p.x, p.y, it.x, it.y);
      if (d < 1.4) cands.push({ d: d - 0.2, label: `Pick up ${it.label}`, run: () => game.emit("pickup", it) });
    }
    if (game.footInteraction) {
      const x = game.footInteraction(p);
      if (x) cands.push(x);
    }
    if (!cands.length) return null;
    cands.sort((a, b) => a.d - b.d);
    return cands[0];
  }
  function findShore(w, x, y, r) {
    let best = null, bd = Infinity;
    for (let dy = -Math.ceil(r); dy <= Math.ceil(r); dy++) {
      for (let dx = -Math.ceil(r); dx <= Math.ceil(r); dx++) {
        const d = Math.hypot(dx, dy);
        if (d > r || d >= bd) continue;
        const tx = x + dx, ty = y + dy;
        const t = w.type(tx, ty);
        if (!WALKABLE[t] || w.isBlocked(tx, ty)) continue;
        if (!WALKABLE[w.type(tx, ty - 0.4)] || w.isBlocked(tx, ty - 0.4)) continue;
        bd = d;
        best = { x: Math.floor(tx) + 0.5, y: Math.floor(ty) + 0.8 };
      }
    }
    return best;
  }
  function disembark(game, p, spot) {
    const s = p.ship;
    if (s) {
      s.captain = null;
      s.sail = 0;
      s.rowing = 0;
      s.anchored = true;
      s.passengers = s.passengers.filter((x) => x !== p);
    }
    p.mode = "foot";
    p.onShip = false;
    p.x = spot.x;
    p.y = spot.y;
    p.vx = p.vy = 0;
    game.emit("disembark", s, spot);
    game.audio?.sfx("step");
  }
  function board(game, p, s) {
    p.mode = "sail";
    p.ship = s;
    p.onShip = true;
    p.inWater = false;
    s.captain = p;
    p.x = s.x;
    p.y = s.y;
    p.setBlock(false);
    p.action = null;
    game.emit("board", s);
    game.hint("sailing", "Sailing: W raises the sails, S lowers them, A/D steer. Hold SPACE to row (works without wind). Left-click fires a broadside toward the mouse. E near land to go ashore.");
    game.audio?.sfx("board");
  }

  // src/game/playerController.js
  var PlayerController = class {
    constructor(game) {
      this.game = game;
      this.aimT = 0;
      this.interaction = null;
    }
    update(p, dt, game) {
      const inp = game.input;
      if (game.ui && game.ui.blocksInput()) {
        p.intent.mx = 0;
        p.intent.my = 0;
        p.intent.sprint = false;
        p.setBlock(false);
        return;
      }
      if (p.mode === "sail") return this.sail(p, dt, game);
      let mx = 0, my = 0;
      if (inp.isDown("W") || inp.isDown("ArrowUp")) my -= 1;
      if (inp.isDown("S") || inp.isDown("ArrowDown")) my += 1;
      if (inp.isDown("A") || inp.isDown("ArrowLeft")) mx -= 1;
      if (inp.isDown("D") || inp.isDown("ArrowRight")) mx += 1;
      const l = Math.hypot(mx, my);
      if (l > 0) {
        mx /= l;
        my /= l;
      }
      p.intent.mx = mx;
      p.intent.my = my;
      p.intent.sprint = inp.isDown("Shift") && l > 0;
      const [wx, wy] = game.renderer.toWorld(game.world, inp.mouse.x, inp.mouse.y);
      const aim = Math.atan2(wy - (p.y - 0.5), game.world.dx(p.x, wx));
      this.aimT = Math.max(0, this.aimT - dt);
      const fighting = inp.mouseDown(0) || inp.mouseDown(2) || inp.isDown("F");
      if (fighting) this.aimT = 0.7;
      if (p.action && p.action.def.track !== false && p.action.t < (p.action.def.windup ?? 0.1)) p.facing = aim;
      else if (!p.action) {
        if (this.aimT > 0) p.facing = aim;
        else if (l > 0) p.facing = Math.atan2(my, mx);
      }
      this.mouseWorld = { x: wx, y: wy };
      if (inp.mousePressed(0) || inp.mouseDown(0) && !p.action) {
        p.facing = aim;
        p.tryM1(game);
      }
      if (inp.mousePressed(2)) {
        p.facing = aim;
        p.tryHeavy(game);
      }
      p.setBlock(inp.isDown("F"));
      if (inp.wasPressed("Space")) p.tryDodge(game, mx, my);
      for (let i = 0; i < 6; i++) {
        if (inp.wasPressed(String(i + 1))) {
          const id = p.hotbar[i];
          if (id) {
            p.facing = aim;
            const target = this.aimTarget(p, game, wx, wy);
            p.tryTechnique(id, game, target || { x: wx, y: wy });
          }
        }
      }
      if (inp.wasPressed("R")) this.toggleHaki(p, game, "armament");
      if (inp.wasPressed("T")) this.toggleHaki(p, game, "observation");
      if (inp.wasPressed("G")) {
        if (p.hakiLevel("conqueror")) {
          p.facing = aim;
          p.tryTechnique("haki_conqueror", game);
        }
      }
      if (inp.wasPressed("Q")) game.emit("quickHeal");
      this.interaction = findInteraction(game, p);
      if (inp.wasPressed("E") && this.interaction) {
        inp.consume("E");
        this.interaction.run();
      }
    }
    aimTarget(p, game, wx, wy) {
      let best = null, bd = 3.5 * 3.5;
      for (const a of game.actorsNear(wx, wy, 3.5)) {
        if (a === p || a.state !== "idle" || !game.combat.canHit(p, a, {})) continue;
        const d = game.world.dist2(wx, wy, a.x, a.y);
        if (d < bd) {
          bd = d;
          best = a;
        }
      }
      return best;
    }
    toggleHaki(p, game, type) {
      if (!p.hakiLevel(type)) return;
      if (type === "armament") {
        p.armament = !p.armament;
        if (p.armament) {
          p.observation = false;
          game.fx.burst(p.x, p.y - 0.8, 10, { color: "#212121", speed: 3, g: 0, life: 0.35, kind: "line" });
          game.audio?.sfx("haki");
        }
      } else {
        p.observation = !p.observation;
        if (p.observation) {
          p.armament = false;
          game.fx.ring(p.x, p.y, 0.5, 8, "#ce93d8", 0.6, 0.08);
          game.audio?.sfx("haki_obs");
        }
      }
    }
    sail(p, dt, game) {
      const inp = game.input;
      const s = p.ship;
      if (!s || s.sunk) return;
      s.captain = p;
      let turn = 0;
      if (inp.isDown("A") || inp.isDown("ArrowLeft")) turn -= 1;
      if (inp.isDown("D") || inp.isDown("ArrowRight")) turn += 1;
      const steer = s.def.turn * (game.crewMods?.turnMul || 1) * (0.35 + 0.65 * clamp(Math.abs(s.speed) / 3, 0, 1));
      s.heading += turn * steer * dt;
      if (inp.isDown("W") || inp.isDown("ArrowUp")) {
        s.sail = Math.min(1, s.sail + dt * 0.9);
        s.anchored = false;
      }
      if (inp.isDown("S") || inp.isDown("ArrowDown")) s.sail = Math.max(0, s.sail - dt * 1.2);
      s.rowing = inp.isDown("Space") ? 1 : 0;
      if (s.rowing) s.anchored = false;
      const [wx, wy] = game.renderer.toWorld(game.world, inp.mouse.x, inp.mouse.y);
      this.mouseWorld = { x: wx, y: wy };
      if (inp.mousePressed(0)) {
        if (!s.fireBroadside(game, wx, wy, p) && !s.def.cannons) game.log("This boat has no cannons.", "#b0bec5");
      }
      if (inp.wasPressed("Shift") && s.def.coupDeBurst) {
        if (s.burstCd <= 0) {
          s.burstCd = 30;
          s.coupT = 1.2;
          game.fx.burst(s.x, s.y, 30, { color: ["#e1f5fe", "#ffffff"], speed: 6, g: 5, life: 0.8, kind: "smoke", size: 0.4 });
          game.fx.shake(0.5);
          game.fx.text(s.x, s.y - 2, "COUP DE BURST!", "#ffeb3b", 0.6);
          game.audio?.sfx("explosion");
        }
      }
      p.x = s.x;
      p.y = s.y;
      p.facing = s.heading;
      this.interaction = findInteraction(game, p);
      if (inp.wasPressed("E") && this.interaction) {
        inp.consume("E");
        this.interaction.run();
      }
      for (let i = 0; i < 6; i++) {
        if (inp.wasPressed(String(i + 1))) {
          const id = p.hotbar[i];
          if (id) {
            p.facing = Math.atan2(wy - p.y, game.world.dx(p.x, wx));
            p.tryTechnique(id, game, { x: wx, y: wy });
          }
        }
      }
    }
    whileKnocked(p, dt, game) {
      game.emit("playerKnockedTick", dt);
    }
  };

  // src/game/stats.js
  var ATTRS = {
    str: { name: "Strength", short: "STR", desc: "Physical damage and carrying power." },
    agi: { name: "Agility", short: "AGI", desc: "Move speed, dodge recovery and attack speed." },
    end: { name: "Endurance", short: "END", desc: "Stamina pool, defence and stamina regeneration." },
    vit: { name: "Vitality", short: "VIT", desc: "Maximum health and recovery." },
    wil: { name: "Willpower", short: "WIL", desc: "Your spirit: resistance to fear, your chance to get back up, and the strength of any hidden power you awaken." }
  };
  var ATTR_KEYS = Object.keys(ATTRS);
  var ATTR_CAP = 100;
  function baseAttrs() {
    return { str: 5, agi: 5, end: 5, vit: 5, wil: 5 };
  }
  function derive(a, mods = {}) {
    const hpMul = mods.hpMul || 1;
    return {
      maxHp: Math.round((90 + a.vit * 9 + a.end * 2) * hpMul),
      maxStamina: Math.round(100 + a.end * 3 + a.agi),
      maxHaki: Math.round(40 + a.wil * 4),
      speed: 4.3 * (1 + a.agi * 45e-4) * (mods.stride || 1) * (mods.speedMul || 1),
      dmg: 1 + a.str * 0.028,
      def: clamp(a.end * 35e-4 + (mods.armor || 0), 0, 0.55),
      staminaRegen: 16 + a.end * 0.25,
      hpRegen: 0.25 + a.vit * 0.02,
      hakiRegen: 1.5 + a.wil * 0.06,
      atkSpeed: 1 + a.agi * 3e-3
    };
  }
  function doriki(a, extra = {}) {
    const sum = a.str * 1.3 + a.agi * 0.9 + a.end * 1 + a.vit * 0.8 + a.wil * 0.8;
    const mastery = (extra.mastery || 0) * 0.6;
    const haki = (extra.haki || 0) * 1.2;
    const fruit = extra.fruit ? 60 + (extra.fruitMastery || 0) * 0.8 : 0;
    const p = sum + mastery + haki + fruit;
    return Math.round(Math.pow(p, 1.55) * 0.35);
  }
  function threatFactor(enemyPower, playerPower) {
    if (!playerPower) return 1;
    const r = enemyPower / playerPower;
    if (r < 0.55) return 0;
    return clamp((r - 0.55) / 0.45, 0, 1.6);
  }

