      dialogue: (ctx) => ({ start: "a", nodes: { a: { text: () => ctx.game.quests.isDone("baratie_krieg") ? '"You fought for this restaurant like one of us. Hungry? Of course you are."' : '"Welcome, you shitty customer! Sit down, eat, pay, get out!"' } } })
