      dialogue: (ctx) => ({ start: "a", nodes: {
        a: { text: () => {
          if (done(ctx, "arlong_park")) return `"Eight years... We're free. Take as many tangerines as you want. Bell-m\xE8re would have liked you."`;
          if (ctx.char.race === "fishman") return `"...A fish-man. Are you one of Arlong's? No? Then why are you here \u2014 to make fun of us?"`;
          return `"Every adult in Cocoyasi pays Arlong 100,000 berries a month \u2014 or dies. My mother, Bell-m\xE8re, couldn't pay for both of us... and he shot her in front of our tangerine grove. My sister has been working for Arlong for eight years to buy the village back."`;
        }, choices: [
          { text: "I'll free Cocoyasi from Arlong.", if: () => !ctx.quest("arlong_park"), do: (c) => c.startQuest("arlong_park"), end: true },
          { text: "Arlong Park has fallen.", if: () => active(ctx, "arlong_park", "report"), do: (c) => c.complete("arlong_park"), next: "a" },
          { text: "Buy tangerines", do: (c) => c.open("shop", { shop: ["tangerine", "rice_ball", "fish_stew"], building: { name: "Nojiko's Grove", role: "shop" } }) },
          { text: "Take care.", end: true }
        ] }
      } })
