      level: 5,
      ai: "idle",
      dialogue: () => ({ start: "a", nodes: { a: { text: `"Shhh! I'm setting up a prank for Corazon, dasuyan. He falls for EVERYTHING \u2014 hot tea, banana peels, a bucket on the door... And he never yells! He can't. He's mute, dasuyan."` } } })
