      bulk: 1.2,
      level: 30,
      boss: true,
      hpMul: 1,
      faction: "pirate",
      style: "brawler",
      moves: ["p1_spring_hopper", "p1_spring_snipe", "brawl_knee"],
      bounty: 55e6,
      infamy: true,
      breakthrough: 3,
      skill: 0.5,
      alert: `"Hahaha! A dreamer! The age of dreams is OVER, idiot!"`,
      barks: ["Spring Hopper!", "Hahahaha!"],
      marker: (c, g) => !g.quests.state("p1_mock_town") ? "!" : null,
      when: (c) => !c.bosses.includes("p1_bellamy"),
      dialogue: (ctx) => ({
        start: "a",
        nodes: {
          a: {
            text: `"Hahaha! Look at this one! You want to go to the sky? Find the One Piece? IDIOT! The age of pirate dreams is over \u2014 what matters now is money and a big bounty. Mine's fifty-five million. Yours?"`,
            choices: [
              { text: "Take that back.", if: () => !ctx.quest("p1_mock_town"), do: (c) => c.startQuest("p1_mock_town"), end: true },
              { text: "Walk away.", end: true }
            ]
          }
        }
      })
