      game.emit("questEvent", "rang_bell", o);
      const bid = o.bell || o.spot || (o.name || "").toLowerCase().replace(/[^a-z0-9]+/g, "_");
      if (bid) game.emit("questEvent", `rang_bell:${bid}`, o);
